//! Compatibility with scripts generated by Roundcube's managesieve plugin.
//! The fixtures are captured from a real Roundcube (see fixtures/roundcube/README.md).

use std::path::Path;

use sieve_core::compat::{is_roundcube_format, roundcube_risks};
use sieve_core::model::{Join, RuleItem};
use sieve_core::{export, import, PrintOptions};

fn fixtures() -> Vec<(String, String)> {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/roundcube");
    let mut out: Vec<_> = std::fs::read_dir(dir)
        .unwrap()
        .flatten()
        .map(|e| e.path())
        .filter(|p| p.extension().is_some_and(|e| e == "sieve"))
        .map(|p| {
            let name = p.file_name().unwrap().to_string_lossy().into_owned();
            (name, std::fs::read_to_string(&p).unwrap())
        })
        .collect();
    out.sort();
    out
}

/// Hand-written inputs uploaded to Roundcube, not Roundcube output.
fn is_foreign_input(name: &str) -> bool {
    name.contains("-before") && name.starts_with(['1', '2']) && !name.starts_with("13") && !name.starts_with("15")
}

/// Exporting an imported Roundcube script gives exactly the same bytes, so
/// sieve-gui and Roundcube can edit the same script alternately.
#[test]
fn roundcube_output_roundtrips_byte_exact() {
    // 18b ends with a bare action that Roundcube wrote without `if true`;
    // sieve-gui writes "all messages" rules the way Roundcube generates them.
    let exceptions = ["18b-foreign-unknown-after-roundcube-edit.sieve"];
    let mut checked = 0;
    for (name, src) in fixtures() {
        if is_foreign_input(&name) || exceptions.contains(&name.as_str()) {
            continue;
        }
        let set = import(&src).unwrap_or_else(|e| panic!("{name}: {e}"));
        let out = export(&set, &PrintOptions::roundcube());
        assert_eq!(out, src, "{name} changed:\n{out}");
        checked += 1;
    }
    assert!(checked >= 25, "only {checked} fixtures checked");
}

/// Everything Roundcube can express except the extensions sieve-gui does not
/// model yet becomes rule cards.
#[test]
fn roundcube_rules_become_cards() {
    for (name, src) in fixtures() {
        if is_foreign_input(&name) {
            continue;
        }
        let set = import(&src).unwrap();
        for item in &set.items {
            if let RuleItem::Raw(raw) = item {
                // editheader, enotify, variables, duplicate, :index, :mime, and
                // a plain `if false` (an enabled rule whose test is `false`)
                let unsupported = [
                    "addheader", "deleteheader", "notify", "set ", "string ", "duplicate", ":index", ":mime",
                    "if false\r\n",
                ];
                assert!(
                    unsupported.iter().any(|u| raw.code.contains(u)),
                    "{name}: unexpected raw block:\n{}",
                    raw.code
                );
            }
        }
    }
}

#[test]
fn roundcube_semantics() {
    let all = fixtures();
    let get = |n: &str| import(&all.iter().find(|(name, _)| name.starts_with(n)).unwrap().1).unwrap();
    let rules = |n: &str| {
        get(n)
            .items
            .into_iter()
            .filter_map(|i| match i {
                RuleItem::Rule(r) => Some(r),
                RuleItem::Raw(_) => None,
            })
            .collect::<Vec<_>>()
    };

    let mixed = rules("07");
    assert_eq!(mixed.iter().map(|r| r.enabled).collect::<Vec<_>>(), vec![true, false, false, true]);
    assert!(mixed[2].conditions.items.is_empty(), "disabled all-messages rule");

    let negated = rules("08");
    let single = negated.iter().find(|r| r.name == "single test anyof").unwrap();
    assert_eq!(single.conditions.join, Join::Any);

    let names: Vec<_> = rules("02").into_iter().map(|r| r.name).collect();
    assert!(names.iter().any(|n| n == "ends with ]"), "{names:?}");

    assert!(get("16a").items.is_empty());
    assert!(get("17b").preamble.as_deref().unwrap().starts_with("# Hand-written script"));
}

/// Roundcube output is never reported as at risk in Roundcube; the
/// hand-written inputs that Roundcube damaged are.
#[test]
fn roundcube_risks_match_what_roundcube_did() {
    for (name, src) in fixtures() {
        let risks = roundcube_risks(&import(&src).unwrap());
        match name.split('-').next().unwrap() {
            // free-standing comment dropped (17b); unknown test and action,
            // nested if and elsif chain dropped or rewritten (18b)
            "17a" => assert_eq!(risks.raw_blocks.len(), 1, "{name}"),
            "18a" => assert_eq!(risks.raw_blocks.len(), 4, "{name}"),
            // bracket comment: Roundcube showed no rules and replaced them (19b)
            "19a" => assert!(risks.bracket_comments, "{name}"),
            // edge-case names that Roundcube dropped (22b), see README
            "22a" => {}
            _ => assert!(risks.is_empty(), "{name}: {risks:?}"),
        }
        let unnamed = ["16a", "16c"].iter().any(|n| name.starts_with(n));
        assert_eq!(is_roundcube_format(&src), !unnamed, "{name}");
    }
}
